import random

class RandomWithReplacement:
    def __init__(self, prob):
        self.prob = prob
        self.alias_table = {}
        self.head_pointer = 0
        self.tail_pointer = 0

        while self.head_pointer != 0 and self.tail_pointer != len(self.prob):
            j = self.tail_pointer
            k = self.head_pointer
            self.alias_table[j] = k
            self.q[k] += self.q[j] - 1
            self.tail_pointer -= 1
            if self.q[k] >= 1:
                self.tail_pointer += 1
                self.head_pointer -= 1

    def random_with_replacement(self, n):
        answer = [0] * n
        for i in range(n):
            ru = random.random() * len(self.prob)
            k = int(ru)
            ru -= k
            if ru < self.q[k]:
                answer[i] = k
            else:
                answer[i] = self.alias_table[k]

        return answer

