from pathlib import Path
from xml.etree import ElementTree

class TextOperations:
    @staticmethod
    def GetFilteredText(filename, encoding, xml_filtering):
        if not isinstance(filename, Path) or not isinstance(encoding, str):
            raise TypeError("filename and encoding must be a Path object and a string, respectively")

        with open(filename, encoding=encoding) as f:
            file_contents = f.read()

        if xml_filtering:
            file_contents = TextOperations.FilterXML(file_contents)
        else:
            file_contents = file_contents

        return file_contents

    @staticmethod
    def FilterXML(xml_string):
        try:
            tree = ElementTree.fromstring(xml_string)
        except ElementTree.ParseError:
            return xml_string

        return ElementTree.tostring(tree, encoding='unicode')

