import com.google.common.reflect.TypeParameter;
import com.google.common.reflect.TypeToken;

class TypeUtils {
    public static String getFormalTypeParametersString(TypeToken<?> type) {
        TypeParameter<?>[] typeParameters = type.getTypeParameters();
        if (typeParameters.length == 0) {
            return "";
        }

        StringBuilder builder = new StringBuilder("<");
        String separator = "";
        for (TypeParameter<?> typeParameter : typeParameters) {
            builder.append(separator);
            separator = ", ";
            appendTypeParameterWithBounds(typeParameter, builder);
        }
        return builder.append(">").toString();
    }

    private static void appendTypeParameterWithBounds(TypeParameter<?> typeParameter, StringBuilder builder) {
        String name = typeParameter.getName();
        TypeToken<?>[] bounds = typeParameter.getBounds();
        if (bounds.length == 0) {
            builder.append(name);
        } else {
            builder.append(name).append(" extends ");
            String separator = "";
            for (TypeToken<?> bound : bounds) {
                builder.append(separator);
                separator = " & ";
                builder.append(bound.getTypeName());
            }
        }
    }
}

