import com.google.common.reflect.TypeToken;

class TypeUtils {
    public static String getFormalTypeParametersString(TypeToken<?> type) {
        return "<" + type.getTypeParameters().stream()
            .map(TypeUtils::appendTypeParameterWithBounds)
            .collect(Collectors.joining(", ")) + ">";
    }

    private static String appendTypeParameterWithBounds(TypeParameter<?> typeParameter) {
        String name = typeParameter.getName();
        TypeToken<?>[] bounds = typeParameter.getBounds();
        return bounds.length == 0 ? name : name + " extends " +
            Arrays.stream(bounds).map(TypeToken::getTypeName).collect(Collectors.joining(" & "));
    }
}

