import java.time.Instant;
import java.time.ZoneOffset;
import java.time.temporal.ChronoField;

public class TimeUtils {

    public static long currentTimeMicros() {
        // Java 8 support lower precision wall time.
        if (javaVersion() == 8) {
            return TimeUnit.MILLISECONDS.toMicros(System.currentTimeMillis());
        }

        // Java 9+ support higher precision wall time.
        Instant now = Clock.systemUTC().instant();
        return TimeUnit.SECONDS.toMicros(now.getEpochSecond()) + TimeUnit.NANOSECONDS.toMicros(now.get(ChronoField.NANO_OF_SECOND));
    }

    private static int javaVersion() {
        return Integer.parseInt(System.getProperty("java.specification.version").split("\\.")[1]);
    }
}

