class ModelIdGenerator:
    def __init__(self):
        self.generatedModelIds = {}

    def generateModelId(self):
        # Get the current time in milliseconds
        mid = int(time.time() * 1000)

        # Check if the time has already been used
        if mid in self.generatedModelIds:
            # Get the last model ID generated for this time
            lastId = self.generatedModelIds[mid]

            # Increment the last model ID
            lastId += 1

        else:
            # Set the last model ID to -1 if it has not been used
            lastId = -1

        # Add the last model ID to the dictionary
        self.generatedModelIds[mid] = lastId

        # Return the model ID
        return mid + lastId

