    # Waiter function
    def wait():
        # Get the resource status
        response = client.describe_cache_clusters(waiter_parameters)
        status = response.get("CacheClusters", [{}])[0].get("CacheClusterStatus")
        # Check if the resource is in desired state
        if status == "deleted":
            return True
        elif status == "cacheClusterNotFound":
            return True
        elif status == "available":
            return True
        elif status == "creating":
            return True
        elif status == "incompatibleNetwork":
            return True
        elif status == "modifying":
            return True
        elif status == "restore failed":
            return True
        elif status == "snapshotting":
            return True
        else:
            return False
    # Return the waiter
    return wait

