def get_from_storage(tsdb, branch_id, display_name):
    leaf = Leaf()
    leaf.setDisplayName(display_name)

    get = GetRequest(tsdb.treeTable(), branch_id)
    get.family(Tree.TREE_FAMILY())
    get.qualifier(leaf.columnQualifier())

    class GetCB(Callback):
        def __init__(self):
            self.leaf = Leaf()
            self.leaf.setDisplayName(display_name)

        def on_success(self, row):
            if row is None or len(row) == 0:
                return Deferred.fromResult(None)

            leaf_json = row[0].value().decode('utf-8')
            self.leaf = json.loads(leaf_json)
            return Deferred.fromResult(self.leaf)

        def on_failure(self, error):
            return Deferred.fromResult(None)

    return tsdb.getClient().get(get).addCallbackDeferring(GetCB())

