from bs4 import BeautifulSoup

# Create a new, clean document
class Cleaner:
    def __init__(self, dirtyDocument):
        self.clean = BeautifulSoup("", "html.parser")
        self.dirty = dirtyDocument

    def Clean(self):
        # Only use elements from the dirt document's <code>body</code>
        if self.dirty.body:
            self.copySafeNodes(self.dirty.body)

        return self.clean

    # Copy only safe nodes to the clean document
    def copySafeNodes(self, nodeList):
        for node in nodeList:
            if self.isSafeNode(node):
                self.appendNode(self.clean.body, self.cloneNode(node))

    # Check if the node is safe to copy
    def isSafeNode(self, node):
        return node.name in WHITELIST or node.name == "text"

    # Clone a node
    def cloneNode(self, node):
        if node.name == "text":
            return node
        else:
            return BeautifulSoup("", "html.parser").new_tag(node.name, node.attrs)

    # Append a node to a parent
    def appendNode(self, parent, child):
