def finalize_handler(b: Bootstrap, ops_factory: OperationFactory, child_listener: ConnectionObserver) -> None:
    # Verify that the input parameters are of the correct types
    if not isinstance(b, Bootstrap):
        raise ValueError("bootstrap must be a Bootstrap instance")
    if not isinstance(ops_factory, OperationFactory):
        raise ValueError("ops_factory must be an OperationFactory instance")
    if not isinstance(child_listener, ConnectionObserver):
        raise ValueError("child_listener must be a ConnectionObserver instance")

    # Get the current child handler
    pipeline = b.config().child_handler()
    if not isinstance(pipeline, BootstrapPipelineHandler):
