import java.io.BufferedReader
import java.io.IOException
import java.net.MalformedURLException
import java.net.URL

class URLReader {

    private final Map<String, String> parameters

    URLReader(URL url, Map<String, String> parameters) {
        this.parameters = parameters
    }

    BufferedReader newReader() throws MalformedURLException, IOException {
        URL configuredURL = configureURL(parameters, url)
        return newBufferedReader(configuredURL)
    }

    private URL configureURL(Map<String, String> parameters, URL url) {
        parameters.each { key, value ->
            if (key == 'connectTimeout') {
                url.connectTimeout = value.toInteger()
            } else if (key == 'readTimeout') {
                url.readTimeout = value.toInteger()
            } else if (key == 'useCaches') {
                url.useCaches = value.toBoolean()
            } else if (key == 'allowUserInteraction') {
                url.allowUserInteraction = value.toBoolean()
            } else {
                url.setRequestProperty(key, value)
            }
        }
        return url
    }

    private BufferedReader newBufferedReader(URL url) throws IOException {
        return new BufferedReader(new InputStreamReader(url.openStream()))
    }

}

