import math

class TouchSlop:
    def __init__(self):
        self.mInitialMotionX = {}
        self.mInitialMotionY = {}
        self.mLastMotionX = {}
        self.mLastMotionY = {}
        self.mTouchSlop = 0

    def checkTouchSlop(self, directions, pointerId):
        if pointerId not in self.mInitialMotionX:
            return False

        check_horizontal = directions & DIRECTION_HORIZONTAL == DIRECTION_HORIZONTAL
        check_vertical = directions & DIRECTION_VERTICAL == DIRECTION_VERTICAL

        dx = self.mLastMotionX[pointerId] - self.mInitialMotionX[pointerId]
        dy = self.mLastMotionY[pointerId] - self.mInitialMotionY[pointerId]

        if check_horizontal and check_vertical:
            return math.sqrt(dx**2 + dy**2) > self.mTouchSlop
        elif check_horizontal:
            return abs(dx) > self.mTouchSlop
        elif check_vertical:
            return abs(dy) > self.mTouchSlop
        else:
            return False

