import java.util.ArrayList;
import java.util.List;

public class MasterWorkerInfo {
    private String address;
    private int port;
    private List<String> tasks;

    public MasterWorkerInfo(String address, int port, List<String> tasks) {
        this.address = address;
        this.port = port;
        this.tasks = tasks;
    }

    public String getAddress() {
        return address;
    }

    public int getPort() {
        return port;
    }

    public List<String> getTasks() {
        return tasks;
    }
}

public class Master {
    private List<MasterWorkerInfo> tempWorkers;
    private List<MasterWorkerInfo> lostWorkers;

    public MasterWorkerInfo findUnregisteredWorker(String workerNetAddress) {
        List<MasterWorkerInfo> workers = new ArrayList<>();
        workers.addAll(tempWorkers);
        workers.addAll(lostWorkers);

        for (MasterWorkerInfo worker : workers) {
            if (worker.getAddress().equals(workerNetAddress)) {
                return worker;
            }
        }
        return null;
    }
}

