import java.lang.reflect.Method;

public class LocalClassUtils {
    public static Class<?> getLocalClassType(Class<?> declaringClass, int occurrence, String name) throws ClassNotFoundException {
        // Get the method
        Method getLocalClassMethod = declaringClass.getDeclaredMethod("getLocalClass", int.class, String.class);
        // Invoke the method
        return (Class<?>) getLocalClassMethod.invoke(null, occurrence, name);
    }
}

