class ClassFieldVisitor:
    def __init__(self, clazz, includeFinalMethods, visitor):
        self.clazz = clazz
        self.includeFinalMethods = includeFinalMethods
        self.visitor = visitor
        self.clazzName = self.clazz.getName().replace('.', '/')
        self.clazzPath = self.clazz.getResource(self.clazzName).getPath()

    def visit(self, access, name, descriptor, signature, value):
        if self.includeFinalMethods or (access & Opcodes.ACC_FINAL) == 0:
            self.visitor.visitField(access, name, descriptor, signature, value)

    def visitEnd(self):
        pass

