import java.util.ArrayList;
import java.util.List;

public class SubscriptOperator {

    public static List<Long> getAt(long[] array, IntRange range) {
        RangeInfo info = subListBorders(array.length, range);
        List<Long> result = new ArrayList<>();
        for (int i = info.from; i <= info.to - 1; i++) {
            result.add(array[i]);
        }
        if (info.reverse) {
            result = reverse(result);
        }
        return result;
    }

    public static RangeInfo subListBorders(int len, IntRange range) {
        int from = Math.max(range.start, 0);
        int to = Math.min(range.end, len);
        boolean reverse = false;
        if (from > to) {
            reverse = true;
            int temp = from;
            from = to;
            to = temp;
        }
        return new RangeInfo(from, to, reverse);
    }

    public static List<Long> reverse(List<Long> list) {
        for (int i = 0; i < list.size() / 2; i++) {
            long temp = list.get(i);
            list.set(i, list.get(list.size() - i - 1));
            list.set(list.size() - i - 1, temp);
        }
        return list;
    }

    public static class RangeInfo {
        public final int from;
        public final int to;
        public final boolean reverse;

        public RangeInfo(int from, int to, boolean reverse) {
            this.from = from;
            this.to = to;
            this.reverse = reverse;
        }
    }
}

