import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;

public class SparseMatrixParser {
    public static SparseMatrix parse(Path path) throws IOException {
        try (InputStream stream = Files.newInputStream(path)) {
            List<String> lines = Files.readAllLines(path);
            int n = Integer.parseInt(lines.get(0));
            int m = Integer.parseInt(lines.get(1));
            int[][] data = new int[n][m];
            for (int i = 2; i < lines.size(); i++) {
                String[] values = lines.get(i).split(" ");
                int row = Integer.parseInt(values[0]);
                int col = Integer.parseInt(values[1]);
                int val = Integer.parseInt(values[2]);
                data[row][col] = val;
            }
            return new SparseMatrix(path.toString(), n, m, data);
        }
    }
}

