def synthesize(token, posTag, posTagRegExp):
    if posTag is not None and posTagRegExp:
        myPosTag = re.sub(r'\\\+INDT$', '', posTag)
        det = ''

        if posTag.endswith('\\+INDT'):
            myPosTag = re.sub(r'\\\+INDT$', '', posTag)
            det = re.sub(r'^(.+) (.+)$', r'\1', aVsAnRule.suggestAorAn(token.getLemma()))
            det = re.sub(r'^(.+) (.+)$', r'\1', det)
        elif posTag.endswith('\\+DT'):
            myPosTag = re.sub(r'\\\+DT$', '', posTag)
            det = 'the '

        possibleTags = initPossibleTags()
        p = re.compile(myPosTag)
        results = []
        for tag in possibleTags:
            m = re.search(p, tag)
            if m:
                lookup(token.getLemma(), tag, results, det)
        return results
    return synthesize(token, posTag)

