class UndertowMessages:
    class MESSAGES:
        class responseAlreadyStarted:
            def __init__(self):
                pass

class UndertowLogger:
    class ERROR_RESPONSE:
        class debugf:
            def __init__(self, a, RuntimeException, "Setting error code %s for exchange %s", statusCode, this):
                pass

class Exchange:
    def __init__(self):
        self.state = 0

    def is_response_sent(self, statusCode):
        return (self.state & FLAG_RESPONSE_SENT) != 0

    def set_state(self, statusCode):
        self.state = (self.state & ~MASK_RESPONSE_CODE) | (statusCode & MASK_RESPONSE_CODE)

    def setStatusCode(self, statusCode):
        # Check if the status code is valid
        if statusCode < 0 or statusCode > 999:
            raise ValueError("Status code must be between 0 and 999")

        # Check if the response has already been sent
        if self.is_response_sent(statusCode):
            raise UndertowMessages.MESSAGES.responseAlreadyStarted()

        # Update the status code
        self.set_state(statusCode)

