class Parse(object):
    def __init__(self, name: str, stream: IO):
        self.reader = BufferedReader(InputStreamReader(stream))
        self.line = self.reader.readLine()

        if self.line is None:
            raise ParseError("EMPTY DATA SOURCE.")

        self.tokens = self.line.split("\t")
        self.p = (len(self.tokens) - 2) // 2
        self.line = self.reader.readLine()

        if self.line is None:
            raise ParseError("PREMATURE END OF FILE.")

        self.samples = self.line.split("\t")
        if len(self.samples) != len(self.tokens) - 1:
