        self.attributes = [None] * self.p
        for i in range(self.p):
            self.attributes[i] = NumericAttribute(self.tokens[2 * i + 2], self.samples[2 * i + 1])

        self.line = self.reader.readLine()
        if self.line is None:
            raise ParseError("PREMATURE END OF FILE.")

        self.n = int(self.line)
        if self.n <= 0:
            raise ParseError("INVALID NUMBER OF ROWS: " + str(self.n))

        self.data = AttributeDataset(name, self.attributes)

        for i in range(self.n):
            self.line = self.reader.readLine()
            if self.line is None:
                raise ParseError("PREMATURE END OF FILE.")

            self.tokens = self.line.split("\t")
            if len(self.tokens) != len(self.samples) + 1:
                raise ParseError("INVALID NUMBER OF ELEMENTS OF LINE %d: %d" % (i + 4, len(self.tokens)))

