v1_code:
class ReferencedTypes(TypeVisitor):
    INSTANCE = ReferencedTypes()

    def visitDeclared(self, type, elements):
        elements.add(type)

    def visitError(self, type, elements):
        pass

    def visitArray(self, type, elements):
        elements.add(type.getComponentType())

    def visitDeclared(self, type, elements):
        for member in type.getMembers().values():
            member.accept(self, elements)

    def visitExecutable(self, type, elements):
        for param in type.getParameterTypes():
            elements.add(param)
        type.getThrownTypes().forEach(elements::add)

    def visitIntersection(self, type, elements):
        for member in type.getBounds():
            member.accept(self, elements)

    def visitUnion(self, type, elements):
        for member in type.getBounds():
            member.accept(self, elements)

def referencedTypes(type):
    elements = ImmutableSet.builder()
    type.accept(ReferencedTypes.INSTANCE, elements)
    return elements.build()

