class MathOperations:
    @staticmethod
    def CalculateBreaks(x: list, h: float) -> list:
        if not isinstance(x, list) or not isinstance(h, float):
            raise ValueError("Input must be a list and a float")

        breaks = [x[0]]
        while breaks[-1] < x[-1]:
            breaks.append(breaks[-1] + h)
        return breaks

