class NameMapping:
    """Interface for name mapping implementations"""
    def map(self, name):
        """Maps a name to a canonical name"""
        raise NotImplementedError()

class ChainedNameMapping(NameMapping):
    """Chains multiple name mappings together"""
    def __init__(self, *mappings):
        self.mappings = mappings

    def map(self, name):
        for mapping in self.mappings:
            mapped_name = mapping.map(name)
            if mapped_name is not None:
                return mapped_name

class DynamicNameMapping(NameMapping):
    """Dynamically changes the name mapping"""
    def __init__(self, name_mapping):
        self.name_mapping = name_mapping

    def map(self, name):
        return self.name_mapping.map(name)

class DefaultNameMapping(NameMapping):
    """Default name mapping"""
    def map(self, name):
        return name

