        self.block_worker = block_worker

    def cache_block_from_ufs(self, block_id, block_size, open_ufs_block_options):
        # Check if block is cached
        if not self.block_worker.open_ufs_block(Sessions.ASYNC_CACHE_SESSION_ID, block_id, open_ufs_block_options):
            LOG.warn("Failed to async cache block {} from UFS on opening the block", block_id)
            return False

        # Copy block from UFS
        try:
            with self.block_worker.read_ufs_block(Sessions.ASYNC_CACHE_SESSION_ID, block_id, 0):
                offset = 0
                while offset < block_size:
                    buffer_size = min(8 * Constants.MB, block_size - offset)
                    reader.read(offset, buffer_size)
                    offset += buffer_size
        except AlluxioException | IOException e:
            # This is only best effort
            LOG.warn("Failed to async cache block {} from UFS on copying the block: {}", block_id, e)
            return False
        finally:
