class WhiteboxImpl:
    def __init__(self, obj):
        self.obj = obj

    def invokeMethod(self, methodToExecute, arguments):
        if not hasattr(self.obj, methodToExecute):
            raise AttributeError(f'Object {self.obj} has no attribute {methodToExecute}')
        method = getattr(self.obj, methodToExecute)
        if not isinstance(method, MethodType):
            raise TypeError(f'Object {self.obj} attribute {methodToExecute} is not a method')
        return method(*arguments)

