def wait_until_active(dynamo, table_name):
    # Wait up to 10 minutes for the table to become active.
    for _ in range(600):
        # Check the table's status every minute.
        time.sleep(60)

        # If the table exists...
        if dynamo.describe_table(TableName=table_name):
            # Get the table description.
            description = dynamo.describe_table(TableName=table_name)

            # If the table is in the ACTIVE state...
            if description["Table"]["TableStatus"] == "ACTIVE":
                # Return from the function.
                return

        # If the table does not exist, then throw an exception.
        if not dynamo.describe_table(TableName=table_name):
            raise TableNeverTransitionedToStateException(
                f"The specified table '{table_name}' does not exist or does not transition into the 'ACTIVE' state."
