class ArmeriaServer:
    def __init__(self,armeriaSettings,meterRegistry,meterIdPrefixFunctionFactory,healthCheckers,armeriaServerConfigurators,thriftServiceRegistrationBeans,httpServiceRegistrationBeans,annotatedServiceRegistrationBeans):
        self.armeriaSettings = armeriaSettings
        self.meterRegistry = meterRegistry
        self.meterIdPrefixFunctionFactory = meterIdPrefixFunctionFactory
        self.healthCheckers = healthCheckers
        self.armeriaServerConfigurators = armeriaServerConfigurators
        self.thriftServiceRegistrationBeans = thriftServiceRegistrationBeans
        self.httpServiceRegistrationBeans = httpServiceRegistrationBeans
        self.annotatedServiceRegistrationBeans = annotatedServiceRegistrationBeans

    def configurePorts(self,server,ports):
        for port in ports:
            server.port(ServerPort(port.getPort(), port.getProtocols()))

    def configureThriftServices(self,server,thriftServiceRegistrationBeans,
                                meterIdPrefixFuncFactory,docsPath):
        for thriftServiceRegistrationBean in thriftServiceRegistrationBeans:
            serviceRegistrationBean = thriftServiceRegistrationBean
            server.service(serviceRegistrationBean.getServiceName(),
                           serviceRegistrationBean.createService(meterIdPrefixFuncFactory, docsPath))

    def configureHttpServices(self,server,httpServiceRegistrationBeans,
                              meterIdPrefixFuncFactory):
        for httpServiceRegistrationBean in httpServiceRegistrationBeans:
            serviceRegistrationBean = httpServiceRegistrationBean
            server.service(serviceRegistrationBean.getServiceName(),
                           serviceRegistrationBean.createService(meterIdPrefixFuncFactory))

    def configureAnnotatedHttpServices(self,server,annotatedServiceRegistrationBeans,
                                       meterIdPrefixFuncFactory):
        for annotatedServiceRegistrationBean in annotatedServiceRegistrationBeans:
            serviceRegistrationBean = annotatedServiceRegistrationBean
            server.service(serviceRegistrationBean.getServiceName(),
                           serviceRegistrationBean.createService(meterIdPrefixFuncFactory))

    def configureServerWithArmeriaSettings(self,server,armeriaSettings,
                                           meterRegistry,healthCheckers):
        server.portUnificationEnabled(armeriaSettings.isPortUnificationEnabled())
        server.use(ArmeriaSettingsConfigurator(armeriaSettings,meterRegistry,healthCheckers))
        server.use(ArmeriaServerConfigurator(armeriaSettings,meterRegistry))

    def armeriaServer(self):
        if not self.armeriaSettings.isEnableMetrics() and not self.thriftServiceRegistrationBeans and not self.httpServiceRegistrationBeans and not self.annotatedServiceRegistrationBeans:
            # No services to register, no need to start up armeria server.
            return None

        if self.armeriaSettings.isEnableMetrics():
            meterIdPrefixFuncFactory = self.meterIdPrefixFunctionFactory.orElse(DEFAULT)
        else:
            meterIdPrefixFuncFactory = None

        server = ServerBuilder()

        ports = self.armeriaSettings.getPorts()
        if ports is None:
            server.port(ServerPort(DEFAULT_PORT.getPort(), DEFAULT_PORT.getProtocols()))
        else:
            self.configurePorts(server,ports)

        self.configureThriftServices(server,self.thriftServiceRegistrationBeans.orElseGet(Collections::emptyList),
                                     meterIdPrefixFuncFactory,self.armeriaSettings.getDocsPath())
        self.configureHttpServices(server,self.httpServiceRegistrationBeans.orElseGet(Collections::emptyList),
                                   meterIdPrefixFuncFactory)
        self.configureAnnotatedHttpServices(server,self.annotatedServiceRegistrationBeans.orElseGet(Collections::emptyList),
                                            meterIdPrefixFuncFactory)
        self.configureServerWithArmeriaSettings(server,self.armeriaSettings,
                                                self.meterRegistry.orElse(Metrics.globalRegistry),
                                                self.healthCheckers.orElseGet(Collections::emptyList))

        for configurators in self.armeriaServerConfigurators:
            configurator = configurators
            configurator.configure(server)

        s = server.build()
        s.start().handle((result,t) -> {
            if t is not None:
                raise IllegalStateException("Armeria server failed to start", t)
            return result
        }).join()
        logger.info("Armeria server started at ports: {}", s.activePorts())
        return s

