    def __init__(self, log_index: int, members: List[str], local_endpoint: str):
        if not isinstance(log_index, int) or log_index < 0:
            raise ValueError("Invalid log index")
        if not isinstance(members, list) or not all(isinstance(member, str) for member in members):
            raise ValueError("Invalid members list")
        if not isinstance(local_endpoint, str):
            raise ValueError("Invalid local endpoint")

        self.log_index = log_index
        self.members = members
        self.local_endpoint = local_endpoint

    def index(self) -> int:
        return self.log_index

    def members(self) -> List[str]:
        return self.members

    def local_endpoint(self) -> str:
        return self.local_endpoint

class RaftGroupMembersService:
    def __init__(self, local_endpoint: str):
        self.last_group_members = None
        self.committed_group_members = None
        self.local_endpoint = local_endpoint

    def restore_group_members(self, log_index: int, members: List[str]):
        if self.last_group_members is not None and self.last_group_members.index() <= log_index:
            # There is no leader state to clean up
            self.group_members = RaftGroupMembers(log_index, members, self.local_endpoint)
            self.committed_group_members = self.group_members
            self.last_group_members = self.group_members
        else:
            raise ValueError("Cannot restore group members")

