def get_qualifier_length(qualifier: bytes, offset: int) -> int:
    # Check if the qualifier is null or the offset is outside the qualifier array
    if qualifier is None or offset < 0 or offset + 1 > len(qualifier):
        raise ValueError("Invalid qualifier or offset")

    # Check the first byte of the qualifier for the millisecond flag
    if qualifier[offset] & MS_BYTE_FLAG == MS_BYTE_FLAG:
        # Check if the offset is greater than or equal to the qualifier length
        if offset + 4 > len(qualifier):
            raise ValueError("Detected a millisecond flag but qualifier length is too short")

        # Return the length of the qualifier as 4 bytes
        return 4
    else:
        # Return the length of the qualifier as 2 bytes
        return 2

