code:
public static void putAt(List self, List splice, List values) {
        if (splice.isEmpty()) {
            if ( ! values.isEmpty() )
                throw new IllegalArgumentException("Trying to replace 0 elements with "+values.size()+" elements");
            return;
        }
        Object first = splice.iterator().next();
        if (first instanceof Integer) {
            if (values.size() != splice.size())
                throw new IllegalArgumentException("Trying to replace "+splice.size()+" elements with "+values.size()+" elements");
            Iterator<?> valuesIter = values.iterator();
            for (Object index : splice) {
                putAt(self, (Integer) index, valuesIter.next());
            }
        } else {
            throw new IllegalArgumentException("Can only index a List with another List of Integers, not a List of "+first.getClass().getName());
        }
    }

v1_code:
def put_at(self, splice, values):
    # Check if splice is empty
    if len(splice) == 0:
        # Check if values is empty
        if len(values) != 0:
            raise Exception("Trying to replace 0 elements with {} elements".format(len(values)))
        else:
            return

    # Get the first element from splice
    first = splice[0]

    # Check if first is an instance of Integer
    if isinstance(first, int):
        # Check if the length of values is equal to the length of splice
        if len(values) != len(splice):
            raise Exception("Trying to replace {} elements with {} elements".format(len(splice), len(values)))
        else:
            # Iterate over each index in splice
            for index in splice:
                # Put index into self
                self[index] = values.pop(0)
    else:
        raise Exception("Can only index a List with another List of Integers, not a List of {}".format(first.__class__.__name__))

