def explode_api_path(uri: str) -> List[str]:
    split = uri.split("/")
    index = 1
    if len(split) < 1 or split[0].lower() != "api":
        raise IllegalArgumentException("The URI does not start with \"/api\"")
    if len(split) < 2:
        root = [""]
        return root
    if split[1].lower().startswith("v") and split[1].length() > 1 and Character.isDigit(split[1].charAt(1)):
        index = 2
    if len(split) - index == 0:
        root = [""]
        return root
    path = [split[index]]
    path_idx = 1
    for i in range(index + 1, len(split) - 1):
        path[path_idx] = split[i]
        path_idx = path_idx + 1
    return path

