import math

class Pool:
    def __init__(self):
        self.size = 0
        self.in_use = 0
        self.free = 0

    def get(self, size):
        self.size += size
        self.in_use += size
        self.free -= size
        return math.factorial(size)

    def trim(self):
        self.size -= self.in_use
        self.in_use = 0
        self.free = 0

